 private int d(int n){return(int)(n*getResources().getDisplayMetrics().density+.5f);} private String lang(){return getSharedPreferences("offer_studio_settings",MODE_PRIVATE).getString("lang","ar");} private boolean rtl(){return!"en".equals(lang());} private String t(String e,String a,String k){return"ar".equals(lang())?a:("ku".equals(lang())?k:e);} private boolean eq(String s,String e,String a,String k){return s.equals(e)||s.equals(a)||s.equals(k);}
