 private void walk(View v){if(v instanceof Button)small((Button)v);if(v instanceof CheckBox)smallCheck((CheckBox)v);if(v instanceof LinearLayout&&serviceCard((ViewGroup)v)){v.setVisibility(View.GONE);return;}if(v instanceof Button){Button b=(Button)v;String s=String.valueOf(b.getText()).trim();if(eq(s,"Share PDF","مشاركة PDF","PDF هاوبەش بکە"))b.setOnClickListener(x->{File f=pdf();if(f!=null)share(f);});else if(eq(s,"Save PDF","حفظ PDF","PDF پاشەکەوت بکە"))b.setOnClickListener(x->{pending=pdf();if(pending!=null){Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/pdf");i.putExtra(Intent.EXTRA_TITLE,pending.getName());startActivityForResult(i,SAVE62);}});}if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)walk(g.getChildAt(i));}}
